"""File command: send a file to the chat."""

from __future__ import annotations

import logging
import os

logger = logging.getLogger(__name__)

class FileCommandsMixin:
    """Command ``/archivo``: download a file generated by the agent."""

    async def _cmd_archivo(self, chat_id: int, path: str | None = None) -> None:
        """Send a generated attachment from DB to the chat.

        Filesystem paths are rejected. Only names in the ``attachments``
        table (populated for generated images/audios) can be sent. The
        bytes come from DB, never from disk.

        Args:
            chat_id: The Telegram chat id.
            path: Attachment file name, or ``None`` to ask for it.
        """
        if not path:
            self._awaiting[chat_id] = "archivo"
            await self.send_message(
                chat_id, "¿Qué archivo querés? (nombre o 'cancelar')"
            )
            return
        await self.send_message(
            chat_id, "Pedí el archivo por nombre desde la app; no se envían rutas del servidor."
        )
